/** Map whatever the host sends ('zh-CN', 'pt-BR', 'el', 'ZH_tw', 'gr') to a TREK language code. */
function normalizeLang(input) {
  const raw = String(input || '').trim().replace('_', '-');
  if (!raw) return 'en';
  if (S[raw]) return raw;
  const low = raw.toLowerCase();
  if (/^zh-(tw|hk|mo|hant)/.test(low)) return 'zh-TW';
  if (low.startsWith('zh')) return 'zh';
  if (low.startsWith('pt')) return 'br';
  if (low.startsWith('el')) return 'gr';
  const base = low.split('-')[0];
  return S[base] ? base : 'en';
}

const intlLocale = (lang) => LOCALES[lang] || 'en-US';
const pdfLang = (lang) => (PDF_FALLBACK.has(lang) ? 'en' : lang);

function fill(str, vars) {
  return String(str).replace(/\{(\w+)\}/g, (m, k) => (vars && vars[k] !== undefined ? String(vars[k]) : m));
}

/** Translator for one language: t(key, vars) and t.n(key, count). */
function translator(lang) {
  const dict = S[lang] || S.en;
  const rules = new Intl.PluralRules(intlLocale(lang));
  const t = (key, vars) => fill(dict[key] !== undefined ? dict[key] : S.en[key] !== undefined ? S.en[key] : key, vars);
  t.n = (key, count) => {
    const forms = dict[key] || S.en[key];
    const form = forms[rules.select(count)] || forms.other;
    return fill(form, { n: count.toLocaleString(intlLocale(lang)) });
  };
  t.lang = lang;
  t.locale = intlLocale(lang);
  return t;
}

/** Everything the tab needs: its strings, the locale for Intl, text direction. */
function uiBundle(lang) {
  return { lang, locale: intlLocale(lang), dir: RTL.has(lang) ? 'rtl' : 'ltr', strings: { ...S.en, ...(S[lang] || {}) }, pdfInEnglish: PDF_FALLBACK.has(lang) };
}

module.exports = { normalizeLang, translator, uiBundle, intlLocale, pdfLang, LANGS: Object.keys(S) };
